import re

with open('unpacked/word/document.xml', 'r', encoding='utf-8') as f:
    lines = f.readlines()

# Find all runs with sz=24 and Helvetica Light
print("All runs with sz=24 / Helvetica Light:")
for i, line in enumerate(lines, 1):
    if 'w:sz w:val="24"' in line:
        # look ahead up to 8 lines for the w:t text
        for j in range(i, min(i+8, len(lines)+1)):
            m = re.search(r'<w:t[^>]*>([^<]*)</w:t>', lines[j-1])
            if m:
                print(f"  Line {i}: text={m.group(1)!r}")
                break

